const body = $input.first().json;
const message = body.message;

if (!message) {
  // Not a message event (could be an edited message, callback query, etc.) - skip
  return [];
}

const senderPhone = message.chat.id.toString(); // keeping field name for downstream compatibility
const senderName = [message.from?.first_name, message.from?.last_name].filter(Boolean).join(' ') || 'Unknown';
const messageId = message.message_id.toString();
const timestamp = message.date;

// Telegram text messages have a `text` field; other types (photo, sticker, voice, etc.) don't
const messageType = message.text ? 'text' : (Object.keys(message).find(k => ['photo','sticker','voice','document','video','audio','location'].includes(k)) || 'unknown');

// Only support plain text messages for now - reject other types gracefully
if (messageType !== 'text') {
  return [{
    json: {
      senderPhone,
      senderName,
      messageText: '',
      messageId,
      timestamp,
      unsupportedType: true,
      messageType
    }
  }];
}

const rawText = message.text || '';

// Basic payload size guard - avoid extremely long messages overwhelming Ollama
const MAX_MESSAGE_LENGTH = 2000;
if (rawText.length > MAX_MESSAGE_LENGTH) {
  return [{
    json: {
      senderPhone,
      senderName,
      messageText: rawText.slice(0, MAX_MESSAGE_LENGTH),
      messageId,
      timestamp,
      unsupportedType: false,
      messageType,
      truncated: true
    }
  }];
}

return [{
  json: {
    senderPhone,
    senderName,
    messageText: rawText,
    messageId,
    timestamp,
    unsupportedType: false,
    messageType
  }
}];

const historyRows = $input.all().map(item => item.json);
const currentData = $('Code in JavaScript1').first().json;

// Detect if the current message contains Bangla script (Unicode range U+0980–U+09FF)
const banglaRegex = /[\u0980-\u09FF]/;
const detectedLanguage = banglaRegex.test(currentData.messageText) ? 'BANGLA' : 'ENGLISH';

// Format history oldest-to-newest (Postgres gave us newest-first)
const formattedHistory = historyRows
  .reverse()
  .map(row => {
    const role = row.direction === 'inbound' ? 'Customer' : 'Assistant';
    return `${role}: ${row.message_text}`;
  })
  .join('\n');

const businessInfo = {
  "company_name": "NN Services & Engineering Ltd.",
  "industry": "Premium Real Estate",
  "introduction": "NN Services & Engineering Ltd. (NNSEL) is a premium real estate company based in Dhaka, Bangladesh, specializing in residential and commercial construction projects.",
  "business_hours": "Saturday-Thursday 9:00 AM - 6:00 PM, Friday Closed",
  "services": ["Residential Apartments", "Commercial Spaces", "Custom Construction"],
  "service_locations": ["Dhaka", "Gulshan", "Banani", "Dhanmondi", "Uttara"],
  "pricing_policy": "Pricing varies based on location, size, and specifications. Never quote specific prices - always direct to sales team.",
  "faqs": [
    { "q": "What areas do you operate in?", "a": "Dhaka, including Gulshan, Banani, Dhanmondi, and Uttara." },
    { "q": "Do you offer payment plans?", "a": "Yes, flexible payment plans available - sales team shares details." }
  ]
};

const systemPromptTemplate = `You are a professional Telegram customer service assistant for NN Services & Engineering Ltd. (NNSEL), a premium real estate company in Dhaka, Bangladesh.

BUSINESS INFORMATION (only source of truth - never invent anything not stated here):
${JSON.stringify(businessInfo, null, 2)}

CONVERSATION HISTORY (recent messages with this customer):
${formattedHistory || 'No previous conversation.'}

CURRENT CUSTOMER MESSAGE:
${currentData.messageText}

YOUR RULES:
0. CRITICAL: You are continuing an ongoing conversation. Carefully read the CONVERSATION HISTORY above before replying. Do NOT reintroduce the company or repeat any earlier reply. Directly acknowledge what the customer just said, then ask ONLY the single next missing piece of information (choose from: name, phone, company, product/service interest, requirement, location, budget, timeline, email, preferred contact time). Never repeat a previous message word-for-word or near-word-for-word.
1. LANGUAGE INSTRUCTION - MANDATORY: The system has detected the CURRENT CUSTOMER MESSAGE is written in ${detectedLanguage}. You MUST write your "reply" field in ${detectedLanguage} only, regardless of what language appeared earlier in the conversation history. This is a hard requirement.
2. Be polite, short, and professional. Ask only one or two questions at a time.
3. NEVER invent a price, feature, policy, or delivery date. Only use the BUSINESS INFORMATION provided above.
4. If information is unavailable, tell the customer honestly and offer to connect them with a team member.
5. Do not ask for information the customer already provided in the conversation history.
6. Do not request passwords, payment PINs, OTPs, or sensitive financial data.
7. Collect lead information naturally: name, phone, company, product/service interest, requirement, location, budget, timeline, email, preferred contact time.
8. Set lead_ready to true when you have AT LEAST: phone number, customer name, product/service interest, and basic requirement.
9. Also set lead_ready true immediately if customer says "call me", "I need a quotation", "I am interested", "arrange a meeting", "how can I buy", or similar.
10. Set human_handoff true if: customer asks for a human, complains, seems angry, asks for final pricing/negotiation, asks legal/payment/contract questions, or you don't know the answer.
11. When human_handoff is true, stop sales questions, let customer know a team member will contact them.

YOU MUST RESPOND WITH VALID JSON ONLY. NO markdown, no code fences, no extra text. Exactly this structure:
{
  "reply": "your message to the customer",
  "lead_ready": true or false,
  "human_handoff": true or false,
  "handoff_reason": "reason if human_handoff is true, otherwise empty string",
  "lead_score": 0 to 100,
  "lead": {
    "name": "", "phone": "", "email": "", "company": "", "product_interest": "",
    "requirement": "", "budget": "", "timeline": "", "location": "", "preferred_contact_time": "", "notes": ""
  }
}
Fill in only lead fields you actually know. Leave unknown fields as empty strings.`;

return [{
  json: {
    senderPhone: currentData.senderPhone,
    senderName: currentData.senderName,
    messageText: currentData.messageText,
    prompt: systemPromptTemplate
  }
}];

const ollamaOutput = $input.first().json;
const currentData = $('Code in JavaScript1').first().json;

let aiResponse;
let parseError = null;

try {
  aiResponse = JSON.parse(ollamaOutput.response);
} catch (e) {
  parseError = e.message;
}

// Validate the parsed response has the fields we expect
function isValid(obj) {
  if (!obj || typeof obj !== 'object') return false;
  if (typeof obj.reply !== 'string') return false;
  if (typeof obj.lead_ready !== 'boolean') return false;
  if (typeof obj.human_handoff !== 'boolean') return false;
  if (!obj.lead || typeof obj.lead !== 'object') return false;
  return true;
}

const valid = !parseError && isValid(aiResponse);

// Force lead_ready true on high-intent trigger phrases, regardless of what the model returned
const triggerPhrases = ['call me', 'quotation', 'i am interested', "i'm interested", 'arrange a meeting', 'how can i buy', 'speak to a', 'talk to a'];
const messageLower = currentData.messageText.toLowerCase();
const forcedLeadReady = triggerPhrases.some(phrase => messageLower.includes(phrase));

return [{
  json: {
    senderPhone: currentData.senderPhone,
    senderName: currentData.senderName,
    messageText: currentData.messageText,
    valid: valid,
    parseError: parseError,
    aiReply: valid ? aiResponse.reply : null,
    leadReady: valid ? (aiResponse.lead_ready || forcedLeadReady) : forcedLeadReady,
    humanHandoff: valid ? aiResponse.human_handoff : false,
    handoffReason: valid ? aiResponse.handoff_reason : '',
    leadScore: valid ? aiResponse.lead_score : 0,
    lead: valid ? aiResponse.lead : {}
  }
}];

